468	  let src = arr;
469	  let dst = new Array(n);
470	  for (let width = 1; width < n; width *= 2) {
471	    for (let lo = 0; lo < n; lo += 2 * width) {
472	      const mid = Math.min(lo + width, n);
473	      const hi = Math.min(lo + 2 * width, n);
474	      let i = lo;
475	      let j = mid;
476	      let k = lo;
477	      while (i < mid && j < hi) {
