/**
 * pyrepr.mjs — CPython `repr()` / `str()`, `repr(float)` and
 * `base64.encodebytes()`, reimplemented without RegExp.
 *
 * Everything here mirrors CPython source behaviour:
 *   - float repr  -> Python/pystrtod.c  `PyOS_double_to_string(v, 'r', 0, ...)`
 *                    plus `format_float_short`'s `use_exp` decision.
 *   - str repr    -> Objects/unicodeobject.c `unicode_repr`
 *   - bytes repr  -> Objects/bytesobject.c   `bytes_repr`
 *   - complex     -> Objects/complexobject.c `complex_repr`
 *   - base64      -> Lib/base64.py `encodebytes` (57 input bytes per line)
 */

import {
  PyBool,
  PyNone,
  PyEllipsis,
  PyBytes,
