 * a per-token pattern string ('O' option / 'A' argument / '-' for the first
 * bare `--`), an option-index map, `consume_optional`, `extras`, then the
 * required-argument check followed by the unrecognized-argument check.
 *
 * No RegExp: `_negative_number_matcher` is a hand-written character scan.
 */

import process from 'node:process';

export const PROG = 'test2_executable';
export const USAGE = 'usage: test2_executable [-h] --a A';

export const HELP =
  USAGE +
  '\n' +
  '\n' +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n';

/* ------------------------------------------------------------------ *
 * exit hook
 * ------------------------------------------------------------------ */

/** Thrown after the exit hook returns, so parsing always stops. */
export class ArgparseExit extends Error {
  constructor(code) {
    super('argparse exit ' + code);
    this.code = code;
  }
}

/**
 * Overridable process exit. The default really does terminate the process,
 * exactly like `sys.exit()` inside `ArgumentParser.exit`.
 */
export const exitHook = {
  exit: (code) => process.exit(code),
};

function doExit(code) {
  exitHook.exit(code);
  // Only reached when a test harness replaces the hook with a no-op.
  throw new ArgparseExit(code);
}

/** `ArgumentParser.error`: usage + `prog: error: msg` on stderr, exit 2. */
function errorExit(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(PROG + ': error: ' + message + '\n');
  return doExit(2);
}

/* ------------------------------------------------------------------ *
 * Action table (registration order matters for abbreviation matching)
 * ------------------------------------------------------------------ */

const HELP_ACTION = { kind: 'help', nargs: 0, name: '-h/--help' };
const A_ACTION = { kind: 'store', nargs: null, name: '--a' };

// `_option_string_actions` — an ordered list because CPython iterates the
// dict in insertion order when looking for abbreviations.
const OPTION_STRINGS = [
  ['-h', HELP_ACTION],
  ['--help', HELP_ACTION],
  ['--a', A_ACTION],
];

function lookupOptionString(s) {
  for (let i = 0; i < OPTION_STRINGS.length; i++) {
    if (OPTION_STRINGS[i][0] === s) return OPTION_STRINGS[i][1];
  }
  return null;
}

const PREFIX_CHARS = '-';
const isPrefixChar = (ch) => ch === '-';

/* ------------------------------------------------------------------ *
 * `_negative_number_matcher`  ==  ^-\d+$ | ^-\d*\.\d+$
 * ------------------------------------------------------------------ */

const isDigit = (ch) => ch >= '0' && ch <= '9';

/**
 * Hand-rolled equivalent of argparse's negative-number test. A token that
 * matches is treated as a positional value rather than an option, because
 * this parser registers no options that look like negative numbers.
 * (CPython's `\d` also accepts non-ASCII decimal digits; only ASCII digits
 * are recognised here.)
