  if (s.length < 2 || s.charAt(0) !== '-') return false;
  let i = 1;
  while (i < s.length && isDigit(s.charAt(i))) i++;
  if (i === s.length) return i > 1; // ^-\d+$
  if (s.charAt(i) !== '.') return false;
